// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 salt) public {
        // Any admissible counterparty: a contract exposing the expected supportsToken()
        TokenHolder actor = new TokenHolder(uint8(salt));
        vm.prank(address(actor));
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        // General rule: any admissible caller with zero balance successfully claims the airdrop
        // and ends with tokenBalance 20. The mutant reverts it, leaving the balance 0.
        assertTrue(ok && c.tokenBalance(address(actor)) == 20);
    }
}

contract TokenHolder {
    uint8 private s;
    constructor(uint8 _s) { s = _s; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
